// TypeScript Version: 4.1

/**
* Package catalog metadata.
*/
interface PackageMetadata {
	/**
	* Package description.
	*/
	description: string;

	/**
	* REPL alias (empty string if none).
	*/
	alias: string;

	/**
	* Value type (empty string if not in the REPL namespace).
	*/
	type: string;

	/**
	* Related package names.
	*/
	related: Array<string>;

	/**
	* Boolean indicating whether the package provides a CLI.
	*/
	hasCliTool: boolean;

	/**
	* Boolean indicating whether the package has a native addon.
	*/
	hasNativeAddon: boolean;

	/**
	* Boolean indicating whether the package ships a WebAssembly binary.
	*/
	hasWasm: boolean;
}

/**
* Returns catalog metadata for a specified package name.
*
* @param pkg - package name
* @returns package metadata or null
*
* @example
* var out = packages( '@stdlib/math/base/special/sin' );
* // returns {...}
*/
declare function packages( pkg: string ): PackageMetadata | null;


// EXPORTS //

export = packages;
